# PUT /api/sheets/{sheetId}/people/{personId} — edit a person's name and grade. Invalid values are a
# 400 and a name another person on the sheet has (case and outer spaces ignored) a 409, neither
# writing anything; a person not on the sheet is a 404. The body's version is the one the edit was made
# from: when someone has saved the person since, the edit is a 412 and writes nothing. Responds with the person as stored.
validate:
  class: net.officefloor.hq.app.person.ValidatePerson
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: version
version:
  class: net.officefloor.hq.app.person.CheckPersonVersion
  govern: [ transaction ]
  next: check
check:
  class: net.officefloor.hq.app.person.CheckPersonRename
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.person.ApplyPerson
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.person.SavePerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.RecordPersonEdited
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
# POST /api/sheets/{sheetId}/bulk-settle — settle the selected claims together. Each selected claim is settled by the
# signed-in user exactly as the single settle does (see ApplyClaimStatus), in list order: people in the order they were
# added, a person's claims newest first; one that goes to PENDING counts as settled, and each writes its own
# CLAIM_SETTLED or CLAIM_PENDING and figure lines. Each that cannot be settled (or is not on the sheet) is left as it is
# and counted refused. Responds with how many were settled and how many refused.
validate:
  class: net.officefloor.hq.app.claim.ValidateBulkSettle
  next: settle
settle:
  class: net.officefloor.hq.app.claim.SettleClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkSettle
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: the name is required (kept without the spaces around it), the grade one of A, B or C. */
public class ValidatePerson {
    public void validate(@RequestBody PersonRequest request, Out<PersonValues> values) throws InvalidPersonException {
        values.set(PersonValues.from(request));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Loads a person of the sheet by id; one not on the sheet is a 404. */
public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            PersonRepository people, Out<Person> person) throws PersonNotFoundException {
        Person found;
        try {
            found = people.find(sheetId.trim(), Long.parseLong(personId.trim()));
        } catch (NumberFormatException e) {
            found = null;
        }
        if (found == null) {
            throw new PersonNotFoundException("No person " + personId);
        }
        person.set(found);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

/** An edit must be made from the person's current version; one made from an older version is refused. */
public class CheckPersonVersion {
    public void check(@Val Person person, @Val PersonValues values) throws InvalidPersonException, StalePersonException {
        if (values.version() == null) {
            throw new InvalidPersonException("The version edited is required");
        }
        if (values.version() != person.version()) {
            throw new StalePersonException(person.id());
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

/** A person being edited may not take a name another person on the sheet already has. */
public class CheckPersonRename {
    public void check(@Val Person person, @Val PersonValues values, PersonRepository people)
            throws DuplicatePersonNameException {
        if (people.nameTaken(person.sheetId(), values.name(), person.id())) {
            throw new DuplicatePersonNameException(values.name());
        }
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Applies the edit: the grade is recorded from the from-date (the sheet's today when blank), replacing one recorded
 *  from the same date and keeping the others; a save leaving the grade as the row showed it (in force on the sheet's
 *  today) with the from-date blank records nothing.
 *  The person's own terms become the ones given (null: none). */
public class ApplyPerson {
    public void apply(@Val Person person, @Val PersonValues values, SheetRepository sheets, Out<Person> changed,
            Out<TermsBefore> termsBefore) {
        LocalDate today = sheets.today(person.sheetId());
        List<PersonGrade> grades = new ArrayList<>(person.grades());
        if (values.gradeFrom() != null || !values.grade().equals(person.grade())) {
            LocalDate from = values.gradeFrom() != null ? values.gradeFrom() : today;
            grades.removeIf((g) -> Objects.equals(g.from(), from));
            grades.add(new PersonGrade(values.grade(), from));
            grades.sort(Comparator.comparing(PersonGrade::from, Comparator.nullsFirst(Comparator.naturalOrder())));
        }
        termsBefore.set(new TermsBefore(person.terms()));
        List<PersonGrade> kept = List.copyOf(grades);
        changed.set(new Person(person.id(), person.sheetId(), values.name(), Person.gradeOn(kept, today), person.version() + 1,
                person.retiredFrom(), kept, person.holds(), values.terms()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

public class SavePerson {
    public void save(@Val Person person, @Val PersonValues values, PersonRepository people)
            throws DuplicatePersonNameException, StalePersonException {
        people.update(person, values.version());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes PERSON_EDITED to the audit file once the edit is stored, with terms= at the end when the edit changed the
 * person's own terms (empty when it cleared them). Then writes the
 * figures the change moved (see Rollup). */
public class RecordPersonEdited {
    public void record(@Val Person person, @Val PersonValues values, @Val TermsBefore termsBefore, @Val RollupBefore before, Rollup rollup, Audit audit) {
        audit.record("PERSON_EDITED sheet=" + person.sheetId() + " by=" + values.by() + " name=" + person.name()
                + " grade=" + person.grade() + (java.util.Objects.equals(termsBefore.days(), person.terms()) ? ""
                        : " terms=" + (person.terms() == null ? "" : person.terms())));
        rollup.record(person.sheetId(), values.by(), before);
    }
