import { useSearchParam } from '../../url/useSearchParam';

/** The selected people's ids, kept in the URL (`people`, comma-separated) so a bulk action on people reads them. */
export function useSelectedPeople(): [number[], (ids: number[]) => void] {
  const [raw, setRaw] = useSearchParam('people', (r) => (typeof r === 'string' || typeof r === 'number' ? String(r) : ''));
  const ids = raw
    .split(',')
    .filter((s) => s !== '')
    .map(Number)
